/**
 * Budapest districts for the manual location alternative (BUILD-BRIEF §8.8). The data is generated by
 * scripts/gen-districts.mjs from research/gvh-location/data/stores.csv; never edit districts.json by hand.
 */
import file from './data/districts.json';
import type { LatLon } from './geo';

export interface District extends LatLon {
	/** "01".."23" (stored in StoredLocation.districtId) */
	id: string;
	number: number;
	/** "I".."XXIII" */
	roman: string;
	/** Number of stores (all chains) the centroid was computed from. */
	stores: number;
}

export const DISTRICTS: readonly District[] = Object.freeze(file.districts.map((d) => Object.freeze({ ...d })));

const BY_ID = new Map(DISTRICTS.map((d) => [d.id, d]));

export function districtById(id: string | null | undefined): District | null {
	return id ? (BY_ID.get(id) ?? null) : null;
}
